<script setup>
import {ref,onMounted,computed} from 'vue'
import {ImagePlus,Store,RefreshCw} from 'lucide-vue-next'
const props=defineProps({sender:{type:Object,required:true}})
const data=ref(null),form=ref({name:'',about:''}),busy=ref(false),error=ref(''),notice=ref(''),permission=ref(true),confirm=ref(false)
const labels={PENDING_REVIEW:'Nome em análise pela Meta',APPROVED:'Nome aprovado; aplicação em andamento',DECLINED:'Nome recusado pela Meta',PIN_MISMATCH:'Revisar a verificação em duas etapas',REGISTRATION_FAILED:'Falha ao aplicar o nome',EXPIRED:'Aprovação expirada',COMPLETED:'Nome aprovado e aplicado'}
const status=computed(()=>labels[data.value?.confirmed?.pending_display_name_status]||'')
const messages={submitted:'Atualização enviada. Consulte o perfil para acompanhar a aplicação e a análise do nome.',partial_error:'A atualização do nome falhou; outros campos podem ter sido aceitos. Consulte o perfil.',unknown:'O provedor não confirmou o resultado. Consulte o perfil antes de tentar novamente.',rejected:'A Twilio recusou a atualização. Confira os dados e consulte o perfil antes de reenviar.'}
const dirty=computed(()=>data.value&&(form.value.name!==data.value.draft.name||form.value.about!==data.value.draft.about))
const preview=computed(()=>data.value?.draft.logo_url||data.value?.confirmed?.logo_url||'')
async function api(suffix='',method='GET',body){const upload=body instanceof FormData;const r=await fetch(`/api/voice/whatsapp/senders/${props.sender.id}/profile${suffix}`,{method,headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,...(!upload?{'Content-Type':'application/json'}:{})},...(body?{body:upload?body:JSON.stringify(body)}:{})});if(r.status===403){permission.value=false;return null}const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível atualizar o perfil.');return d}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function hydrate(d){data.value=d;if(d)form.value={name:d.draft.name,about:d.draft.about}}
async function save(){await run(async()=>{hydrate(await api('','PUT',form.value));confirm.value=false;notice.value='Rascunho salvo. Nada foi alterado no WhatsApp.'})}
async function photo(event){const file=event.target.files?.[0];if(!file)return;await run(async()=>{if(file.size>5*1024*1024)throw Error('Escolha uma imagem de até 5 MB.');const fd=new FormData();fd.append('photo',file);data.value=await api('/photo','POST',fd);confirm.value=false;notice.value='Foto guardada no rascunho. Publique após conectar o WhatsApp.'});event.target.value=''}
async function sync(){await run(async()=>{data.value=await api('/sync','POST',{});notice.value='Perfil consultado na Twilio. Seu rascunho foi preservado.'})}
async function publish(){await run(async()=>{data.value=await api('/publish','POST',{confirmed:confirm.value});confirm.value=false;notice.value=messages[data.value?.submission_state]||'Consulte o perfil para confirmar o resultado.'})}
onMounted(()=>run(async()=>hydrate(await api())))
</script>
<template>
 <details v-if="permission" class="public-profile" open>
  <summary><Store :size="18"/>Perfil público do WhatsApp</summary>
  <p class="intro">Nome e foto que representam esta empresa no WhatsApp. O apelido interno do número permanece separado.</p>
  <p v-if="error" class="profile-alert" role="alert">{{error}}</p><p v-if="notice" class="profile-notice" role="status">{{notice}}</p>
  <template v-if="data">
   <div class="profile-preview"><img v-if="preview" :src="preview" alt="Foto do perfil do WhatsApp" referrerpolicy="no-referrer"><span v-else class="avatar"><Store :size="28"/></span><div><span class="eyebrow">PRÉVIA DO RASCUNHO</span><strong>{{form.name||'Nome da empresa'}}</strong><span>{{sender.number}}</span><small>{{form.about||'Seu perfil comercial'}}</small></div></div>
   <form @submit.prevent="save">
    <fieldset :disabled="busy"><label>Nome comercial<input v-model="form.name" required minlength="2" maxlength="255" placeholder="Ex.: Bossa Nova SIR"></label><label>Recado do perfil<input v-model="form.about" maxlength="139" placeholder="Ex.: Atendimento e informações"></label>
    <label class="photo-picker"><ImagePlus :size="18"/><span>Escolher foto</span><input type="file" accept="image/jpeg,image/png" @change="photo"></label><p class="help">JPG ou PNG sem transparência, quadrado, de 640 a 4096 pixels e até 5 MB. A foto publicada ficará visível no WhatsApp.</p><button class="secondary" type="submit">Salvar rascunho</button></fieldset>
   </form>
   <div class="profile-confirmed"><strong>Perfil confirmado pelo provedor</strong><p>{{data.confirmed.name||'Ainda não consultado'}}</p><p v-if="data.confirmed.pending_display_name">Nome solicitado: {{data.confirmed.pending_display_name}}</p><p v-if="status">{{status}}</p><small v-if="data.synced_at">Última consulta: {{new Date(data.synced_at).toLocaleString('pt-BR')}}</small></div>
   <p class="help">A prévia não confirma a publicação. O nome depende da análise da Meta, e a exibição também depende da verificação empresarial e dos contatos salvos pelo destinatário.</p>
   <template v-if="data.can_publish"><label class="profile-consent"><input type="checkbox" v-model="confirm" :disabled="busy||dirty">Confirmo a publicação do rascunho salvo neste número.</label><div class="profile-actions"><button type="button" class="primary" :disabled="busy||dirty||!confirm||['unknown','submitting'].includes(data.submission_state)" @click="publish">Publicar perfil</button><button type="button" class="secondary" :disabled="busy" @click="sync"><RefreshCw :size="14"/>Consultar perfil</button></div><p v-if="dirty" class="help">Salve as alterações antes de publicar.</p></template>
   <p v-else class="profile-notice">Você já pode preparar o perfil. A publicação será liberada depois de conectar este número à API oficial.</p>
  </template>
 </details>
</template>
<style scoped>
.public-profile{margin:20px 0;padding:20px;border:1px solid #dce4d5;border-radius:16px;background:#fcfdf9}.public-profile summary{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:700;cursor:pointer;color:#284939}.intro,.help{font-size:12px;color:#66765e;line-height:1.6}.profile-preview{display:flex;align-items:center;gap:16px;padding:18px;border:1px solid #e0e7d9;border-radius:13px;background:white;margin:18px 0}.profile-preview img,.avatar{width:72px;height:72px;border-radius:50%;object-fit:cover;flex-shrink:0}.avatar{display:grid;place-items:center;background:#ecf2e4;color:#65774e}.profile-preview>div{min-width:0;display:grid;gap:5px;overflow-wrap:anywhere}.profile-preview strong{font-size:18px}.profile-preview small,.profile-preview span:not(.eyebrow){font-size:12px;color:#6d7865}.public-profile fieldset{padding:0;margin:0;border:0;min-width:0}.public-profile label{display:grid;gap:7px;margin:14px 0;font-size:12px;font-weight:600}.public-profile input:not([type=checkbox]):not([type=file]){width:100%;box-sizing:border-box;min-width:0;padding:12px;border:1px solid #d7dfce;border-radius:9px;background:white;font:inherit}.photo-picker{padding:14px;border:1px dashed #bac8ae;border-radius:10px;cursor:pointer}.photo-picker{position:relative}.photo-picker input{position:absolute;width:1px;height:1px;opacity:0}.photo-picker:focus-within{outline:2px solid #b58d34;outline-offset:2px}.profile-confirmed{border-top:1px solid #dfe7d6;margin-top:20px;padding-top:16px;font-size:12px}.profile-confirmed p{margin:7px 0}.profile-confirmed small{color:#75816b}.profile-consent{display:flex!important;align-items:flex-start!important;font-weight:400!important}.profile-consent input{margin:2px 0}.profile-actions{display:flex;gap:10px;flex-wrap:wrap}.profile-actions button{display:flex;gap:7px;align-items:center}.profile-alert{padding:12px;background:#fff0eb;color:#a23923;border-radius:9px;font-size:12px}.profile-notice{padding:12px;background:#eef4e7;color:#45613a;border-radius:9px;font-size:12px}.public-profile button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:600px){.public-profile{padding:14px}.profile-preview{padding:12px;gap:12px}.profile-preview img,.avatar{width:56px;height:56px}.profile-actions>*{flex:1;justify-content:center}}
</style>
